{
  "predictors": [
    {
      "name": "Employee Growth Rate",
      "construction": "Current employee count minus employee count from one year ago, divided by employee count from one year ago.",
      "rationale": "Firms that are rapidly growing their workforce may be expanding operations or investing in new opportunities, potentially leading to higher future profits.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Innovation Intensity",
      "construction": "R&D expenditure over the past year divided by total assets.",
      "rationale": "Firms investing heavily in research and development may be developing new products or technologies, improving future competitive advantage.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Customer Concentration Ratio",
      "construction": "Revenue from top five customers divided by total revenue for the past year.",
      "rationale": "High concentration in revenue sources can reflect strong, stable relationships or potentially risky over-reliance on a few customers.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Management Ownership",
      "construction": "Percentage of shares held by executives and directors as of the latest proxy statement.",
      "rationale": "High management ownership aligns the interests of management with shareholders, possibly leading to better firm performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Geographic Revenue Diversification",
      "construction": "Number of unique countries contributing to revenue as disclosed in the latest annual report.",
      "rationale": "Firms with diversified revenue streams may be less vulnerable to country-specific economic shocks.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "CEO Tenure",
      "construction": "Number of years the current CEO has held their position.",
      "rationale": "Longer-tenured CEOs may have more experience and a deeper understanding of the firm, potentially leading to better strategic decisions.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Strategic Alliance Intensity",
      "construction": "Number of strategic alliances announced in the past year.",
      "rationale": "Firms actively forming alliances may be leveraging external expertise and resources, enhancing growth prospects.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Citation Impact",
      "construction": "Average number of citations per patent over the past five years.",
      "rationale": "Highly-cited patents suggest impactful innovations that can enhance competitive positioning.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Board Diversity Ratio",
      "construction": "Percentage of board members from underrepresented groups.",
      "rationale": "Diverse boards may offer a wider range of perspectives, leading to more innovative problem-solving and improved governance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supply Chain Complexity",
      "construction": "Number of suppliers as disclosed in the latest annual report.",
      "rationale": "A complex supply chain can indicate robust operations and the ability to leverage multiple sources for inputs, reducing dependency risk.",
      "higher_returns_for": "low values of the measure"
    }
  ]
}
